// ECO opening naming + book-deviation detection (spec B / ADR-0028). Pure
// longest-prefix match over a bundled CC0 table. A seed table ships in
// public/openings/eco.json; the full set is regenerated by scripts/build-eco.mjs
// from the Lichess chess-openings TSVs (same seed→ETL pattern as the puzzle DB).

import type { Locale } from '../i18n/translate';

export interface EcoEntry {
  eco: string;
  name: string;
  /** Opening line as UCI moves from the start position. */
  uci: string[];
}

export interface OpeningName {
  eco: string;
  name: string;
  /** Number of plies covered by the matched book line (= first out-of-book ply index). */
  plyInBook: number;
}

/** The deepest book line that is a prefix of (or equals) the played moves. */
export function nameOpening(uci: string[], table: EcoEntry[]): OpeningName | null {
  let best: EcoEntry | null = null;
  for (const e of table) {
    if (e.uci.length > uci.length) continue;
    let prefix = true;
    for (let i = 0; i < e.uci.length; i++) {
      if (e.uci[i] !== uci[i]) { prefix = false; break; }
    }
    if (prefix && (!best || e.uci.length > best.uci.length)) best = e;
  }
  return best ? { eco: best.eco, name: best.name, plyInBook: best.uci.length } : null;
}

/** Ply index at which the game leaves all known book lines (0 if none matched). */
export function firstOutOfBook(uci: string[], table: EcoEntry[]): number {
  return nameOpening(uci, table)?.plyInBook ?? 0;
}

// --- runtime loader (bundled JSON) ----------------------------------------
let cache: EcoEntry[] | null = null;
export async function loadEco(): Promise<EcoEntry[]> {
  if (cache) return cache;
  try {
    const base = (import.meta as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? '/';
    const res = await fetch(`${base}openings/eco.json`);
    cache = res.ok ? ((await res.json()) as EcoEntry[]) : [];
  } catch {
    cache = [];
  }
  return cache;
}

/** Convenience: load the table and name the line in one call. */
export async function describeOpening(uci: string[]): Promise<OpeningName | null> {
  return nameOpening(uci, await loadEco());
}

// --- French display overlay (ETL-safe) ------------------------------------
// eco.json and the build-eco.mjs ETL stay English (regenerated from the
// English Lichess TSVs by `npm run etl:eco`). Rather than translating the seed
// (which the ETL would overwrite), we map English names → conventional French
// opening names at *display* time. Keys MUST match the exact English `name`
// strings in eco.json (note British "Defence" spelling, the typographic
// ellipsis "…", and "López" with an accent). Names with no key fall back to
// English. Refines W18 Q-W18-4 into a robust, ETL-survivable mechanism.
const ECO_NAME_FR: Record<string, string> = {
  // 1. e4 — Sicilian family
  'Sicilian Defence': 'Défense sicilienne',
  'Sicilian, Open (…Nc6)': 'Sicilienne, variante ouverte (…Cc6)',
  'Sicilian (…d6)': 'Sicilienne (…d6)',
  'Sicilian, Najdorf': 'Sicilienne, variante Najdorf',
  'Sicilian, Dragon': 'Sicilienne, variante du Dragon',
  // 1. e4 e5 — open games
  "King's Pawn Game": 'Partie du pion roi',
  'Petrov Defence': 'Défense russe',
  'Open Game (…Nc6)': 'Partie ouverte (…Cc6)',
  'Italian Game': 'Partie italienne',
  'Ruy López': 'Partie espagnole',
  'Scotch Game': 'Partie écossaise',
  "King's Gambit": 'Gambit du roi',
  // 1. e4 e6 / c6 / d5 / d6 / g6 / Nf6
  'French Defence': 'Défense française',
  'French, …d5': 'Française, …d5',
  'Caro-Kann Defence': 'Défense Caro-Kann',
  'Caro-Kann, …d5': 'Caro-Kann, …d5',
  'Scandinavian Defence': 'Défense scandinave',
  'Pirc Defence': 'Défense Pirc',
  'Modern Defence': 'Défense moderne',
  'Alekhine Defence': 'Défense Alekhine',
  // 1. d4 d5 — Queen's pawn / Queen's gambit
  "Queen's Pawn Game": 'Partie du pion dame',
  "Queen's Gambit": 'Gambit dame',
  "Queen's Gambit Declined": 'Gambit dame refusé',
  'Slav Defence': 'Défense slave',
  "Queen's Gambit Accepted": 'Gambit dame accepté',
  // 1. d4 Nf6 — Indian systems
  'Indian Game': 'Défense indienne',
  'Indian, …e6': 'Indienne, …e6',
  'Nimzo-Indian Defence': 'Défense nimzo-indienne',
  'King\'s Indian / Grünfeld setup': 'Est-indienne / structure Grünfeld',
  "King's Indian Defence": 'Défense est-indienne',
  'Grünfeld Defence': 'Défense Grünfeld',
  'Benoni Defence': 'Défense Benoni',
  'Dutch Defence': 'Défense hollandaise',
  // 1. c4 — English
  'English Opening': 'Partie anglaise',
  'English, …e5': 'Anglaise, …e5',
  'Symmetrical English': 'Anglaise symétrique',
  // 1. Nf3 — Réti
  'Réti Opening': 'Partie Réti',
  'Réti, …d5': 'Réti, …d5',
  // 1. d4 / 1. e4 generic
  "Queen's Pawn (…e6/…g6)": 'Partie du pion dame (…e6/…g6)',
  "King's Pawn Opening": 'Ouverture du pion roi',
};

/**
 * Display-name for an opening in the active locale. English is canonical
 * (eco.json); for `fr` we look up the French overlay above and fall back to the
 * English name when no mapping exists. SAN/notation is unaffected.
 */
export function localizedOpeningName(opening: { name: string }, locale: Locale): string {
  return locale === 'fr' ? (ECO_NAME_FR[opening.name] ?? opening.name) : opening.name;
}
